import { type InferredInput, defineScript, gezel } from '@bendyline/gezel-sdk';
import { logStore, rosterStore } from '@bendyline/gezel-sdk/stores';

export const meta = defineScript({
  name: 'pipeline-store',
  description:
    "Read and update the sales pipeline (deals.json) and its activity log (activity.json). action:'status' for the follow-ups due, every open deal by stage and the weighted forecast; 'add' to save a deal (an existing title is updated, never duplicated; valueChange adds to its value); 'move' to change its stage (won and lost close it); 'log' to record a call, email, meeting or note (valueChange there too moves the value); 'follow_up' to set the next touch; 'list' for every deal.",
  inputs: {
    action: {
      type: 'string',
      description: "One of 'status', 'add', 'move', 'log', 'follow_up', or 'list'.",
      required: true,
    },
    id: { type: 'string', description: "Deal id, e.g. 'deal-3'." },
    title: {
      type: 'string',
      description: "The deal's name, e.g. 'Harbor Street Café kitchen rewire'. Also finds it (or its company) when no id is given.",
    },
    company: { type: 'string', description: 'The customer.' },
    contact: { type: 'string', description: 'The person you deal with there.' },
    value: { type: 'number', description: "The deal's whole value in dollars, e.g. 12400." },
    valueChange: {
      type: 'number',
      description: 'Dollars to add to the current value (negative to take off), e.g. 3400 or -500.',
    },
    probability: { type: 'number', description: "Chance to win, 0-100, when it differs from the stage's usual chance." },
    status: { type: 'string', description: 'lead, qualified, proposal, negotiation, won, or lost.' },
    closeAt: { type: 'string', description: 'Expected close date, YYYY-MM-DD.' },
    followUpAt: { type: 'string', description: 'Next follow-up date, YYYY-MM-DD.' },
    inDays: { type: 'number', description: 'Next follow-up this many days from today, instead of followUpAt.' },
    nextStep: { type: 'string', description: 'What the next follow-up is for.' },
    kind: { type: 'string', description: 'For log: call, email, meeting, or note.' },
    source: { type: 'string', description: "Where the lead came from, e.g. 'referral'." },
    note: { type: 'string', description: 'What happened, or why a deal was lost, in the words given.' },
    withinDays: { type: 'number', description: 'How many days ahead counts for follow-ups (default 7).' },
  },
  outputs: {
    open: { type: 'number', description: 'Open deals.' },
    openValue: { type: 'number', description: 'Value of the open deals, in dollars.' },
    weightedForecast: { type: 'number', description: 'Weighted forecast of the open deals, in dollars.' },
    followUpsDue: { type: 'number', description: 'Follow-ups overdue or due today.' },
    summary: { type: 'string', description: 'What changed, then the pipeline picture, or the listing.' },
  },
  requires: ['workspace.read', 'workspace.write', 'reminders'],
} as const);

const input = gezel.input as InferredInput<typeof meta>;

// ── pipeline-rules-start ──
// Pure derivations: money in integer cents, a deal's chance and weighted
// value, local calendar days for follow-ups, finding a deal by name, and the
// pipeline picture the crew reads. Kept self-contained between these
// sentinels so unit tests execute the shipped bytes.
var DAY_MS = 86400000;
var STAGES = ['lead', 'qualified', 'proposal', 'negotiation', 'won', 'lost'];
var OPEN_STAGES = ['lead', 'qualified', 'proposal', 'negotiation'];
var CHANCE = { lead: 10, qualified: 25, proposal: 50, negotiation: 75, won: 100, lost: 0 };
var KINDS = ['call', 'email', 'meeting', 'note'];
var TOUCHES = ['call', 'email', 'meeting', 'note', 'stage', 'won', 'lost'];
var NAME_STOP = ['the', 'and', 'for', 'with', 'our', 'deal', 'job', 'quote', 'bid'];

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}
function localDay(ms) {
  var d = new Date(ms);
  return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
}
function normalizeDate(text) {
  var raw = String(text || '').trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(raw)) return raw.slice(0, 10);
  var parsed = Date.parse(raw);
  return isFinite(parsed) ? localDay(parsed) : null;
}
function daysLeft(day, nowMs) {
  var due = Date.parse(String(day).slice(0, 10) + 'T00:00:00');
  var today = Date.parse(localDay(nowMs) + 'T00:00:00');
  return Math.round((due - today) / DAY_MS);
}
function addDays(day, n) {
  var d = new Date(String(day).slice(0, 10) + 'T12:00:00');
  d.setDate(d.getDate() + n);
  return localDay(d.getTime());
}
function when(days) {
  if (days < 0) return -days + (days === -1 ? ' day late' : ' days late');
  if (days === 0) return 'today';
  if (days === 1) return 'tomorrow';
  return 'in ' + days + ' days';
}
function ago(days) {
  return days <= 0 ? 'today' : days === 1 ? 'yesterday' : days + ' days ago';
}
// Dollars as a number or text ('$12,400', '95.50') to integer cents; null when it is not money.
function toCents(value) {
  if (typeof value === 'string') value = Number(value.replace(/[$,\s]/g, ''));
  if (typeof value !== 'number' || !isFinite(value)) return null;
  return (value < 0 ? -1 : 1) * Math.round(Math.abs(value) * 100);
}
function money(cents) {
  var n = Math.round(Number(cents) || 0);
  var abs = Math.abs(n);
  var whole = String(Math.floor(abs / 100)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return (n < 0 ? '-$' : '$') + whole + (abs % 100 ? '.' + pad(abs % 100) : '');
}
function fold(text) {
  return String(text || '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[‘’]/g, "'")
    .toLowerCase()
    .trim();
}
function isOpen(record) {
  return OPEN_STAGES.indexOf(record.status) >= 0;
}
function chanceOf(record) {
  var p = record.fields && record.fields.probability;
  return typeof p === 'number' && p >= 0 && p <= 100 ? p : CHANCE[record.status] || 0;
}
function valueOf(record) {
  return Number(record.fields && record.fields.valueCents) || 0;
}
// Value times chance, rounded half up to the cent.
function weighted(record) {
  return Math.floor((valueOf(record) * chanceOf(record) + 50) / 100);
}
function sum(records, of) {
  return records.reduce(function (total, r) {
    return total + of(r);
  }, 0);
}
// The deal a person means: its id, its exact title, a title or company that
// contains what they wrote, or one whose name holds every word they used.
// Several matches prefer the open deals; a tie is an error that names them.
function findDeal(records, input) {
  if (input.id) {
    var byId = records.filter(function (r) {
      return r.id === String(input.id).trim();
    });
    if (byId.length) return byId[0];
    if (!input.title && !input.company) throw new Error("No deal '" + input.id + "'. " + roll(records));
  }
  var wanted = fold(input.title || input.company);
  if (!wanted) throw new Error("Pass 'id' (e.g. 'deal-3') or the deal's 'title'. " + roll(records));
  var name = function (r) {
    return fold(r.fields.title);
  };
  var both = function (r) {
    return name(r) + ' ' + fold(r.fields.company);
  };
  var words = wanted.split(/[^a-z0-9']+/).filter(function (w) {
    return w.length > 2 && NAME_STOP.indexOf(w) < 0;
  });
  var tiers = [
    function (r) {
      return name(r) === wanted;
    },
    function (r) {
      return name(r).indexOf(wanted) >= 0 || fold(r.fields.company) === wanted;
    },
    function (r) {
      return (
        words.length > 0 &&
        words.every(function (w) {
          return both(r).indexOf(w) >= 0 || both(r).indexOf(w.replace(/s$/, '')) >= 0;
        })
      );
    },
  ];
  for (var i = 0; i < tiers.length; i++) {
    var hits = records.filter(tiers[i]);
    if (hits.length > 1) {
      var open = hits.filter(isOpen);
      if (open.length) hits = open;
    }
    if (hits.length === 1) return hits[0];
    if (hits.length > 1) {
      throw new Error(
        "More than one deal matches '" + (input.title || input.company) + "': " +
          hits.map(function (r) { return r.id + ' ' + r.fields.title; }).join(', ') + '. Pass id.',
      );
    }
  }
  throw new Error("No deal matches '" + (input.title || input.company) + "'. " + roll(records));
}
function roll(records) {
  var open = records.filter(isOpen);
  return open.length
    ? 'Open deals: ' + open.map(function (r) { return r.id + ' ' + r.fields.title; }).join(', ') + '.'
    : 'There are no open deals.';
}
function lastTouch(record, events) {
  var mine = events.filter(function (e) {
    return e.data && e.data.dealId === record.id && TOUCHES.indexOf(e.kind) >= 0;
  });
  return mine.length ? mine[mine.length - 1].at : record.createdAt;
}
function dealLine(record, events, nowMs) {
  var f = record.fields || {};
  var head = record.id;
  if (f.company && fold(f.title).indexOf(fold(f.company)) < 0) head += ', ' + f.company;
  if (f.contact) head += ', contact ' + f.contact;
  head += ', ' + record.status + ', ' + money(valueOf(record));
  if (isOpen(record)) head += ' at ' + chanceOf(record) + '% = ' + money(weighted(record)) + ' weighted';
  var parts = [head];
  if (f.followUpAt) parts.push('follow up ' + when(daysLeft(f.followUpAt, nowMs)) + ' (' + f.followUpAt + ')' + (f.nextStep ? ': ' + f.nextStep : ''));
  else if (isOpen(record)) parts.push('no follow-up set');
  if (isOpen(record) && f.closeAt) parts.push('expected to close ' + f.closeAt);
  if (!isOpen(record) && f.closedAt) parts.push(record.status + ' ' + f.closedAt + (f.lostReason ? ': ' + f.lostReason : ''));
  var touched = lastTouch(record, events);
  if (touched) parts.push('last touch ' + ago(-daysLeft(localDay(Date.parse(touched)), nowMs)));
  return f.title + ' (' + parts.join('; ') + ')';
}
function followLine(record, nowMs) {
  var f = record.fields;
  return (
    f.title + ' (' + record.id + (f.contact ? ', ' + f.contact : '') + ') ' + when(daysLeft(f.followUpAt, nowMs)) +
    (f.nextStep ? ': ' + f.nextStep : '')
  );
}
function picture(records, events, nowMs, withinDays) {
  var open = records.filter(isOpen);
  var byFollow = function (a, b) {
    return String(a.fields.followUpAt).localeCompare(String(b.fields.followUpAt));
  };
  var due = open
    .filter(function (r) {
      return r.fields.followUpAt && daysLeft(r.fields.followUpAt, nowMs) <= withinDays;
    })
    .sort(byFollow);
  var dueNow = due.filter(function (r) {
    return daysLeft(r.fields.followUpAt, nowMs) <= 0;
  });
  var unset = open.filter(function (r) {
    return !r.fields.followUpAt;
  });
  var month = localDay(nowMs).slice(0, 7);
  var closing = open.filter(function (r) {
    return String(r.fields.closeAt || '').slice(0, 7) === month;
  });
  var recent = function (status) {
    return records.filter(function (r) {
      return r.status === status && r.fields.closedAt && -daysLeft(r.fields.closedAt, nowMs) <= 30;
    });
  };
  var won = recent('won');
  var lost = recent('lost');
  var decided = records.filter(function (r) {
    return r.status === 'won' || r.status === 'lost';
  });
  var wonAll = decided.filter(function (r) {
    return r.status === 'won';
  });
  var parts = [
    open.length + (open.length === 1 ? ' open deal' : ' open deals') + ' worth ' + money(sum(open, valueOf)) +
      '; weighted forecast ' + money(sum(open, weighted)) + '.',
  ];
  // One list, overdue first: a model asked about today reads a separate overdue list as out of scope.
  parts.push(
    due.length
      ? 'Follow-ups within ' + withinDays + ' days, overdue first: ' + due.map(function (r) { return followLine(r, nowMs); }).join(' | ') + '.'
      : 'No follow-ups due in the next ' + withinDays + ' days.',
  );
  if (unset.length) parts.push('No follow-up set: ' + unset.map(function (r) { return r.fields.title + ' (' + r.id + ')'; }).join(', ') + '.');
  var stages = OPEN_STAGES.filter(function (s) {
    return open.some(function (r) { return r.status === s; });
  }).map(function (s) {
    var here = open.filter(function (r) { return r.status === s; });
    return s + ' (' + here.length + ', ' + money(sum(here, valueOf)) + '): ' + here.map(function (r) { return dealLine(r, events, nowMs); }).join(' | ');
  });
  if (stages.length) parts.push('Open deals by stage: ' + stages.join('. ') + '.');
  if (closing.length) {
    parts.push(
      'Expected to close this month: ' + closing.length + (closing.length === 1 ? ' deal, ' : ' deals, ') + money(sum(closing, valueOf)) +
        ', weighted ' + money(sum(closing, weighted)) + '.',
    );
  }
  if (won.length || lost.length) {
    parts.push(
      'Last 30 days: won ' + won.length + ' (' + money(sum(won, valueOf)) + ')' +
        (won.length ? ': ' + won.map(function (r) { return r.fields.title; }).join(', ') : '') +
        '; lost ' + lost.length + ' (' + money(sum(lost, valueOf)) + ')' +
        (lost.length ? ': ' + lost.map(function (r) { return r.fields.title + (r.fields.lostReason ? ' (' + r.fields.lostReason + ')' : ''); }).join('; ') : '') + '.',
    );
  }
  if (decided.length) {
    parts.push('Win rate: ' + wonAll.length + ' of ' + decided.length + ' decided deals (' + Math.round((wonAll.length / decided.length) * 100) + '%).');
  }
  return {
    open: open.length,
    openValueCents: sum(open, valueOf),
    weightedCents: sum(open, weighted),
    followUpsDue: dueNow.length,
    summary: records.length ? parts.join(' ') : 'No deals on the pipeline yet.',
  };
}
// ── pipeline-rules-end ──

type Deal = { id: string; status: string; fields: Record<string, unknown>; createdAt: string };

const deals = rosterStore(gezel.fs, 'deals.json', {
  stages: ['lead', 'qualified', 'proposal', 'negotiation', 'won', 'lost'],
  idPrefix: 'deal',
});
const activity = logStore(gezel.fs, 'activity.json');
const now = Date.now();
const today = localDay(now);

function given(value: unknown): boolean {
  return value !== undefined && value !== null && value !== '';
}

function followUpInput(): string | undefined {
  if (typeof input.inDays === 'number' && isFinite(input.inDays)) return addDays(today, Math.max(0, Math.round(input.inDays)));
  if (given(input.followUpAt)) {
    const day = normalizeDate(input.followUpAt);
    if (!day) throw new Error("followUpAt must be a date, e.g. '2026-11-20', or pass inDays.");
    return day;
  }
  return undefined;
}

async function move(record: Deal, to: string, why?: string): Promise<string> {
  if (STAGES.indexOf(to) < 0) throw new Error("status must be one of: " + STAGES.join(', ') + '.');
  const title = String(record.fields.title);
  if (record.status === to) return title + ' is already ' + to + '.';
  const closing = to === 'won' || to === 'lost';
  await deals.update(record.id, {
    fields: {
      probability: null,
      closedAt: closing ? today : null,
      ...(closing ? { followUpAt: null, nextStep: null } : {}),
      ...(to === 'lost' && why ? { lostReason: why } : {}),
    },
  });
  await deals.transition(record.id, to, why ? { note: why } : {});
  await activity.append({
    kind: closing ? to : 'stage',
    note: why || 'Moved from ' + record.status + ' to ' + to + '.',
    data: { dealId: record.id, from: record.status, to },
  });
  return (
    title + ' moved from ' + record.status + ' to ' + to +
    (to === 'won' ? ': ' + money(valueOf(record)) + ' won' : to === 'lost' && why ? ': ' + why : '') + '.'
  );
}

// The pipeline's one reminder sits on the soonest follow-up, the morning it is due.
async function remindNextFollowUp(): Promise<void> {
  const next = (await deals.list())
    .filter((r) => isOpen(r) && typeof r.fields.followUpAt === 'string')
    .map((r) => ({ record: r, at: Date.parse(String(r.fields.followUpAt) + 'T09:00:00') }))
    .filter((r) => r.at > now)
    .sort((a, b) => a.at - b.at)[0];
  try {
    if (!next || next.at - now > 30 * DAY_MS) await gezel.reminder.clear();
    else {
      const f = next.record.fields;
      await gezel.reminder.set({
        at: new Date(next.at).toISOString(),
        title: ('Follow up: ' + String(f.company || f.title)).slice(0, 80),
        body: (String(f.nextStep || f.title) + ' (' + String(f.title) + ', ' + money(valueOf(next.record)) + ').').slice(0, 160),
      });
    }
  } catch {
    // Reminders are a convenience; the pipeline is the record.
  }
}

const withinDays = typeof input.withinDays === 'number' && input.withinDays > 0 ? Math.round(input.withinDays) : 7;
let note = '';

if (input.action === 'add') {
  const all = (await deals.list()) as Deal[];
  const title = String(input.title || input.company || '').trim();
  let existing: Deal | null = null;
  if (given(input.id)) existing = findDeal(all, { id: input.id, title: input.title });
  // A change to the value is a change to a deal that exists, never a new one.
  else if (given(input.valueChange)) existing = findDeal(all, input);
  else if (title) existing = all.find((r) => fold(r.fields.title) === fold(title)) ?? null;
  if (!existing && !title) throw new Error("add needs 'title': the job or opportunity, e.g. 'Fernwood Studio lighting retrofit'.");
  const status = given(input.status) ? String(input.status).trim().toLowerCase() : '';
  if (status && STAGES.indexOf(status) < 0) throw new Error('status must be one of: ' + STAGES.join(', ') + '.');
  const fields: Record<string, unknown> = {};
  if (input.company) fields.company = input.company.trim();
  if (input.contact) fields.contact = input.contact.trim();
  if (input.source) fields.source = input.source.trim();
  if (input.nextStep) fields.nextStep = input.nextStep.trim();
  if (given(input.closeAt)) {
    const closeAt = normalizeDate(input.closeAt);
    if (!closeAt) throw new Error("closeAt must be a date, e.g. '2026-12-15'.");
    fields.closeAt = closeAt;
  }
  const follow = followUpInput();
  if (follow) fields.followUpAt = follow;
  if (given(input.probability)) {
    const p = Number(input.probability);
    if (!isFinite(p) || p < 0 || p > 100) throw new Error('probability is a percent from 0 to 100.');
    fields.probability = Math.round(p);
  }
  if (given(input.value) && !given(input.valueChange)) {
    const cents = toCents(input.value);
    if (cents === null || cents < 0) throw new Error('value is the amount in dollars, e.g. 12400.');
    fields.valueCents = cents;
  }
  if (existing) {
    let valueNote = '';
    if (given(input.valueChange)) {
      const change = toCents(input.valueChange);
      if (change === null) throw new Error('valueChange is an amount in dollars, e.g. 3400 or -500.');
      const before = valueOf(existing);
      if (before + change < 0) throw new Error(String(existing.fields.title) + ' is ' + money(before) + '; that change would take it below zero.');
      fields.valueCents = before + change;
      valueNote = ': value ' + money(before) + (change < 0 ? ' - ' + money(-change) : ' + ' + money(change)) + ' = ' + money(before + change);
    } else if (fields.valueCents !== undefined) {
      valueNote = ': value now ' + money(fields.valueCents);
    }
    if (given(input.id) && input.title && fold(input.title) !== fold(existing.fields.title)) fields.title = input.title.trim();
    await deals.update(existing.id, { fields });
    note = 'Updated ' + String(existing.fields.title) + valueNote + '.';
    if (status && status !== existing.status) {
      note += ' ' + (await move({ ...existing, fields: { ...existing.fields, ...fields } }, status, input.note));
    } else if (input.note) {
      await activity.append({ kind: 'note', note: input.note, data: { dealId: existing.id } });
    }
  } else {
    const start = status || 'lead';
    const closing = start === 'won' || start === 'lost';
    const record = await deals.add({
      status: start,
      fields: { title, valueCents: 0, ...fields, ...(closing ? { closedAt: today } : {}) },
    });
    await activity.append({
      kind: closing ? start : 'note',
      note: input.note || 'Deal added at ' + start + '.',
      data: { dealId: record.id },
    });
    note = 'Added ' + record.id + ': ' + title + ', ' + money(valueOf(record)) + ', ' + start + '.';
  }
} else if (input.action === 'move') {
  const record = findDeal((await deals.list()) as Deal[], input);
  if (!given(input.status)) throw new Error("move needs 'status': qualified, proposal, negotiation, won, or lost.");
  note = await move(record, String(input.status).trim().toLowerCase(), input.note);
} else if (input.action === 'log') {
  const record = findDeal((await deals.list()) as Deal[], input);
  if (!input.note) throw new Error("log needs 'note': what happened.");
  const kind = KINDS.indexOf(String(input.kind)) >= 0 ? String(input.kind) : 'note';
  await activity.append({ kind, note: input.note, data: { dealId: record.id } });
  const next = followUpInput();
  const due = typeof record.fields.followUpAt === 'string' && daysLeft(record.fields.followUpAt, now) <= 0;
  const fields: Record<string, unknown> = {};
  let valueNote = '';
  if (given(input.valueChange)) {
    const change = toCents(input.valueChange);
    if (change === null) throw new Error('valueChange is an amount in dollars, e.g. 3400 or -500.');
    const before = valueOf(record);
    if (before + change < 0) throw new Error(String(record.fields.title) + ' is ' + money(before) + '; that change would take it below zero.');
    fields.valueCents = before + change;
    valueNote = ' Value ' + money(before) + (change < 0 ? ' - ' + money(-change) : ' + ' + money(change)) + ' = ' + money(before + change) + '.';
  } else if (/\$\s?\d/.test(input.note)) {
    // A note that names an amount usually means the value moved; say it did not.
    valueNote = ' Its value is unchanged at ' + money(valueOf(record)) + '; if the note changes it, call add_deal with valueChange.';
  }
  if (next) {
    fields.followUpAt = next;
    if (input.nextStep) fields.nextStep = input.nextStep.trim();
  } else if (kind !== 'note' && due) {
    // The touch was the follow-up that was due.
    fields.followUpAt = null;
    fields.nextStep = null;
  }
  await deals.update(record.id, { fields });
  note =
    'Logged ' + (kind === 'email' ? 'an ' : 'a ') + kind + ' on ' + String(record.fields.title) +
    (next ? '; next follow-up ' + next + (input.nextStep ? ': ' + input.nextStep.trim() : '') + '.' : kind !== 'note' && due ? '; that was the follow-up that was due, so none is set now.' : '.') +
    valueNote;
} else if (input.action === 'follow_up') {
  const record = findDeal((await deals.list()) as Deal[], input);
  const next = followUpInput();
  if (!next) throw new Error("follow_up needs followUpAt (YYYY-MM-DD) or inDays.");
  if (!isOpen(record)) throw new Error(String(record.fields.title) + ' is ' + record.status + '; move it back to an open stage first.');
  await deals.update(record.id, { fields: { followUpAt: next, ...(input.nextStep ? { nextStep: input.nextStep.trim() } : {}) } });
  await activity.append({
    kind: 'follow-up',
    note: 'Follow up ' + next + (input.nextStep ? ': ' + input.nextStep.trim() : '') + '.',
    data: { dealId: record.id },
  });
  note = String(record.fields.title) + ': follow up ' + when(daysLeft(next, now)) + ' (' + next + ')' + (input.nextStep ? ', ' + input.nextStep.trim() : '') + '.';
} else if (input.action !== 'status' && input.action !== 'list') {
  throw new Error("Unknown action '" + input.action + "'. Use status, add, move, log, follow_up, or list.");
}

const records = (await deals.list()) as Deal[];
const events = await activity.list();
const view = picture(records, events, now, withinDays);
await remindNextFollowUp();

gezel.output({
  open: view.open,
  openValue: view.openValueCents / 100,
  weightedForecast: Math.round(view.weightedCents) / 100,
  followUpsDue: view.followUpsDue,
  summary:
    input.action === 'list'
      ? records
          .slice()
          .sort((a, b) => Number(!isOpen(a)) - Number(!isOpen(b)))
          .map((r) => '[' + r.status + '] ' + dealLine(r, events, now))
          .join('\n') || 'No deals on the pipeline yet.'
      : (note ? note + ' ' : '') + view.summary,
});

